      const rat = sdk.findNearbyNpc(/giant rat/i);
      if (rat) { await bot.attack(rat); }
    }
    const g = sdk.findGroundItem(/^bones$/i);
    if (g) { await bot.pickupItem(g); return true; }
    await sdk.waitForTicks(2);
  }
  return false;
}
