async function getRuneCount(name: string): Promise<number> {
  const inv = sdk.getInventory();
  return inv.find(i => i.name.toLowerCase().includes(name.toLowerCase()))?.count || 0;
}

async function hasRunes(water: number, earth: number, body: number): Promise<boolean> {
  return (await getRuneCount('water rune')) >= water &&
         (await getRuneCount('earth rune')) >= earth &&
         (await getRuneCount('body rune')) >= body;
}

async function hasAirMind(): Promise<boolean> {
  return (await getRuneCount('air rune')) >= 1 && (await getRuneCount('mind rune')) >= 1;
}

